import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function InfluencerLogin({ onClose }) {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        // Initialize icons if lucide is available
        if (window.lucide) {
            window.lucide.createIcons();
        }
    }, []);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setLoginData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email || !loginData.password) {
            toast.error('Please enter both email and password');
            return;
        }

        setLoading(true);
        
        try {
            const response = await fetch('http://localhost:3188/Studio/influencer/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email: loginData.email,
                    password: loginData.password
                })
            });
            
            const data = await response.json();
            
            if (data.success) {
                // Login successful, store user data and redirect
                localStorage.setItem('studioToken', 'simulated-token');
                localStorage.setItem('studioUser', JSON.stringify({
                    id: data.data.id,
                    email: data.data.email,
                    firstName: data.data.firstname,
                    lastName: data.data.lastname,
                    role: 'influencer'
                }));
                
                toast.success('Login successful');
                if (onClose) onClose();
                navigate('/studio/influencer');
            } else {
                toast.error(data.message);
            }
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container-fluid">
            <div className="row justify-content-center">
                <div className="col-12">
                    <div className="text-center mb-4">
                        <h3 className="fw-bold text-dark">Influencer Login</h3>
                        <p className="text-muted">Sign in to your influencer account</p>
                    </div>
                    
                    <div className="card border-0 shadow-sm">
                        <div className="card-body p-4">
                            <form onSubmit={handleSubmit} className="authentication-form">
                                <div className="mb-4">
                                    <label className="form-label" htmlFor="UserEmail">Email Address</label>
                                    <div className="position-relative w-100">
                                        <input 
                                            type="email" 
                                            className="form-control form-control-lg rounded" 
                                            id="UserEmail" 
                                            name="email"
                                            placeholder="Enter your email" 
                                            value={loginData.email}
                                            onChange={handleInputChange}
                                            required 
                                            disabled={loading}
                                        />
                                        <span className="text-muted p-0 position-absolute end-0 top-50 border-0 fs-4 translate-middle-y me-3">
                                            <i className="fas fa-envelope"></i>
                                        </span>
                                    </div>
                                </div>
                                
                                <div className="mb-4">
                                    <div className="d-flex justify-content-between">
                                        <label className="form-label" htmlFor="UserPass">Password</label>
                                        <a href="#" className="text-muted">Forgot password?</a>
                                    </div>
                                    <div className="position-relative w-100">
                                        <input 
                                            type={showPassword ? "text" : "password"}
                                            className="form-control form-control-lg rounded" 
                                            id="UserPass" 
                                            name="password"
                                            placeholder="Enter your password" 
                                            value={loginData.password}
                                            onChange={handleInputChange}
                                            required 
                                            disabled={loading}
                                        />
                                        <button
                                            type="button"
                                            className="btn text-muted p-0 position-absolute end-0 top-50 border-0 fs-4 translate-middle-y me-3"
                                            onClick={() => setShowPassword(!showPassword)}
                                        >
                                            <i className={showPassword ? "fas fa-eye-slash" : "fas fa-eye"}></i>
                                        </button>
                                    </div>
                                </div>
                                
                                <div className="form-check mb-4">
                                    <input type="checkbox" className="form-check-input" id="rememberMe" />
                                    <label className="form-check-label" htmlFor="rememberMe">Remember me</label>
                                </div>
                                
                                <div className="text-center d-grid">
                                    <button 
                                        className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium" 
                                        type="submit"
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                Signing in...
                                            </>
                                        ) : (
                                            <>
                                                <i className="fas fa-sign-in-alt"></i> Sign In
                                            </>
                                        )}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
